data.query:
query HandlingUnit($where: HandlingUnitWhereInput, $orderBy: [HandlingUnitOrderByInput!], $first: Int, $after: String) {
  handlingUnit(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        barcode
        handlingUnitType {
          id
          name
        }
        load {
          id
          number
          scheduledDepartAt
          orders {
            edges {
              node {
                id
                number
              }
            }
          }
          pick {
            id
            number
            user {
              firstName
              lastName
            }
          }
          scac {
            code
            carrier
          }
          shipments {
            edges {
              node {
                 businessPartnerAddress {
                  textAddress
                  businessPartner {
                    name
                  }
                 }
              }
            }
          }
        }
      }
    }
  }
}

query Inventory($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        quantity {
          value
          unitId
          unit {
            name
            code
          }
        }
        expiresAt
        storageUnit {
          id
          code
          name
        }
        product {
          id
          number
          description
        }
        shipmentLine {
          orderLineRelease {
            number
          }
        }
        inventoryPickSteps {
          edges {
            node {
              pickStep {
                pickupStorageUnit {
                  id
                  name
                }
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $isNotNilOrEmpty(inventory.edges) ?
  {
    "documentPayload": {
      "itemInfo": inventory.edges[].node.(
        $unit := quantity.unitId;
        $unitSizeArray := product.productPackaging.productPackagingConfigurations.edges[].node[packagingUnitId = $unit][0].quantity;
        {
          "location": storageUnit.code,
          "quantity": quantity.value & " " & quantity.unit.code,
          "expirationDate": $isNotNilOrEmpty(_customFields.expirationDate) ? $fromMillis($toMillis(_customFields.expirationDate), "[M01]/[Y01]") : ($isNotNilOrEmpty(expiresAt) ? $fromMillis($toMillis(expiresAt), "[M01]/[Y01]") : ""),
          "productId": product.id,
          "description": product.description,
          "itemCode": product.number,
          "unitSize": $unitSizeArray[0],
          "orderLineReleaseNumber": shipmentLine.orderLineRelease.number,
          "pickLocation": inventoryPickSteps.edges[0].node.pickStep.pickupStorageUnit.name
        }
      )
    }
  }
  :
  {
    "documentPayload": {
      "itemInfo": {
        "location": null,
        "quantity": null,
        "expirationDate": null
      }
    }
  }
)

